172	                for (Element option: options) {
173	                    if (isDisabledOption(option)) continue; // disabled options are not successful
174	                    data.add(HttpConnection.KeyVal.create(name, option.val()));
175	                    set = true;
176	                }
177	                if (!set && !el.hasAttr("multiple")) {
178	                    // a single select defaults to its first non-disabled option
179	                    for (Element option : el.select("option")) {
180	                        if (!isDisabledOption(option)) {
181	                            data.add(HttpConnection.KeyVal.create(name, option.val()));
182	                            break;
183	                        }
184	                    }
185	                }
186	            } else if (el.nameIs("textarea")) {
