206	     * textarea wrapping / line break normalization</a>: a lone {@code \r}, a lone {@code \n}, or a {@code \r\n} pair each
207	     * become a single {@code \r\n}. Every other character (spaces, tabs, Unicode, and consecutive blank lines) is copied
208	     * verbatim, and an empty value stays an empty string. Applied only when reading the value, so the DOM is never
209	     * mutated and repeated reads produce the same result (the mapping is idempotent).
210	     */
211	    private static String normalizeTextareaNewlines(String value) {
212	        if (value.indexOf('\r') == -1 && value.indexOf('\n') == -1) return value; // fast path: nothing to normalize
213	
214	        StringBuilder out = new StringBuilder(value.length());
215	        for (int i = 0; i < value.length(); i++) {
216	            char c = value.charAt(i);
217	            if (c == '\r') {
218	                out.append("\r\n");
219	                if (i + 1 < value.length() && value.charAt(i + 1) == '\n') i++; // consume the LF of a CRLF pair
220	            } else if (c == '\n') {
221	                out.append("\r\n");
222	            } else {
223	                out.append(c);
224	            }
225	        }
226	        return out.toString();
227	    }
