245	     * excepted from that fieldset's disabling (but may still be disabled by their own attribute or another
246	     * ancestor fieldset). Evaluated from the live DOM on each call.
247	     */
248	    private static boolean isDisabled(Element el) {
249	        if (el.hasAttr("disabled")) return true;
250	        for (Element parent = el.parent(); parent != null; parent = parent.parent()) {
251	            if (parent.nameIs("fieldset") && parent.hasAttr("disabled") && !inFirstLegend(parent, el))
252	                return true;
253	        }
254	        return false;
255	    }
256	
257	    /**
258	     * Tests if {@code el} descends from the first {@code legend} element child of {@code fieldset} (which must be an
259	     * ancestor of {@code el}). Only that first direct-child legend is excepted; later or nested legends are not.
260	     */
261	    private static boolean inFirstLegend(Element fieldset, Element el) {
262	        Element legend = null;
263	        for (Element child : fieldset.children()) {
264	            if (child.nameIs("legend")) {
265	                legend = child;
266	                break;
267	            }
268	        }
269	        if (legend == null) return false;
270	        for (Element parent = el.parent(); parent != null && parent != fieldset; parent = parent.parent()) {
271	            if (parent == legend) return true;
272	        }
273	        return false;
274	    }
275	
276	    @Override
277	    public FormElement clone() {
278	        return (FormElement) super.clone();
279	    }
280	}
