        boolean absorbsExternals = id.length() > 0 && doc.getElementById(id) == this;

        Set<Element> descendants = new HashSet<>(this.getAllElements());
        Set<Element> linked = new HashSet<>(linkedEls);
        Elements controls = new Elements();
